    wx.chooseImage({
      count: 1,
      sourceType: ['camera', 'album'],
      success: (res) => {
        const filePath = res.tempFilePaths[0]
        wx.cloud.uploadFile({
          cloudPath: `recognize/${Date.now()}.jpg`,
          filePath,
          success: () => {
            wx.navigateTo({ url: '/pages/result/result?mode=recognize' })
